#!/bin/sh
# Bit-exactness check for the ring-buffer PCM path.
#
# Expects reference PCM generated by ffmpeg in tests/assets:
#   ffmpeg -i t.wav  -f s16le -ac 2 t.wav.ref16.pcm
#   ffmpeg -i t.flac -f s16le -ac 2 t.flac.ref16.pcm
#   ffmpeg -i t.wav  -f s24le -ac 2 t.wav.ref24.pcm
#
#   ./tests/compare_pcm.sh /path/to/eac_play /path/to/tests/assets
set -u

BIN=${1:?usage: $0 <eac_play> <assets_dir>}
ASSETS=${2:?usage: $0 <eac_play> <assets_dir>}
rc=0

check() {
    src=$1
    bits=$2
    ref=$3
    ours="$ASSETS/$src.ours$bits.pcm"
    if ! "$BIN" "$ASSETS/$src" --raw-out "$ours" --bits "$bits" -q; then
        echo "$src/${bits}-bit: decode FAILED"
        rc=1
        return
    fi
    if [ ! -f "$ASSETS/$ref" ]; then
        echo "$src/${bits}-bit: missing reference $ref (skipped)"
        return
    fi
    if cmp -s "$ours" "$ASSETS/$ref"; then
        echo "$src/${bits}-bit: IDENTICAL ($(wc -c <"$ours") bytes)"
    else
        echo "$src/${bits}-bit: DIFF"
        cmp -l "$ours" "$ASSETS/$ref" | head -3
        rc=1
    fi
}

check t.wav 16 t.wav.ref16.pcm
check t.flac 16 t.flac.ref16.pcm
check t.wav 24 t.wav.ref24.pcm
check t24.wav 24 t24.wav.ref24.pcm
check t24.flac 24 t24.flac.ref24.pcm

exit $rc
